016,9100000000000001001,910000000000002004,NULL,'A','A06','校企合作开发教材数','DEVELOPMENT','NUMBER','INCREMENT','部','HIGHER_BETTER','AUTO_SUM',1,'五年累计开发并投入使用校企合作教材 30 部。','教材样书、企业参与证明、验收和使用记录。',0,NULL,30.000000,203,6,'DISTRIBUTED',1,'2026-01-05 10:00:00.000',203,'2026-10-25 19:32:01.045',203,0),(910000000000003017,9100000000000001001,910000000000002004,NULL,'A','A07','用人单位满意度','DEVELOPMENT','PERCENT_DIRECT','DIRECT_PERCENT','%','HIGHER_BETTER','AUTO_SUM',1,'到 2030 年用人单位满意度达到 90%，调查须说明来源并附统计材料。','调查报告、样本清单和统计明细。',1,0.8400,0.900000,204,7,'DISTRIBUTED',1,'2026-01-05 10:00:00.000',203,'2026-10-26 16:33:17.795',203,0),(910000000000003018,9100000000000001001,910000000000002005,NULL,'A','A08','企业横向技术服务到款额','DEVELOPMENT','NUMBER','INCREMENT','万元','HIGHER_BETTER','AUTO_SUM',1,'五年累计企业横向技术服务实际到款 600 万元。','技术合同、阶段成果和到账回单。',0,NULL,600.000000,203,8,'DISTRIBUTED',1,'2026-01-05 10:00:00.000',203,'2026-10-25 19:32:01.046',203,0),(910000000000003019,9100000000000001001,910000000000002005,NULL,'A','A09','社会培训服务规模增长','DEVELOPMENT','PERCENT_QUANTIFIABLE','GROWTH','人次','HIGHER_BETTER','AUTO_SUM',1,'以 2025 年 2400 人次为基线，2030 年社会培训达到 3600 人次，五年增长 50%。','培训方案、考勤记录、结业名单和统计报表。',0,2400.0000,3600.000000,204,9,'DISTRIBUTED',1,'2026-01-05 10:00:00.000',203,'2026-10-26 16:33:17.795',203,0),(910000000000003020,9100000000000001001,910000000000002006,NULL,'A','A10','校园文化品牌与实践育人项目完成数','DEVELOPMENT','NUMBER','INCREMENT','项','HIGHER_BETTER','AUTO_SUM',1,'五年累计完成校园文化品牌与实践育人项目 50 项。','项目方案、活动记录和总结评价。',0,NULL,50.000000,204,10,'DISTRIBUTED',1,'2026-01-05 10:00:00.000',203,'2026-10-25 19:32:01.048',203,0),(910000000000003021,9100000000000001001,910000000000002007,NULL,'A','A11','办学条件与智慧校园重点项目完成数','CONSTRAINT','NUMBER','INCREMENT','项','HIGHER_BETTER','AUTO_SUM',1,'五年累计完成办学条件与智慧校园重点项目 30 项。','立项预算、采购合同、验收和使用记录。',0,NULL,30.000000,204,11,'DISTRIBUTED',1,'2026-01-05 10:00:00.000',203,'2026-10-25 19:32:01.048',203,0),(910000000000003022,9100000000000001001,910000000000002007,NULL,'A','A12','校内实训工位规模','CONSTRAINT','NUMBER','STOCK','个','HIGHER_BETTER','AUTO_SUM',1,'以 2025 年 3200 个为基线，2030 年可用校内实训工位达到 4000 个。','资产台账、验收和投入使用记录。',0,3200.0000,4000.000000,204,12,'DISTRIBUTED',1,'2026-01-05 10:00:00.000',203,'2026-10-26 16:33:17.795',203,0),(910000000000003023,9100000000000001001,910000000000002008,NULL,'A','A13','国（境）外交流与合作项目完成数','DEVELOPMENT','NUMBER','INCREMENT','项','HIGHER_BETTER','AUTO_SUM',1,'五年累计完成具有实质活动与成果的国（境）外交流合作项目 12 项。','合作协议、实施记录和项目总结。',0,NULL,12.000000,204,13,'DISTRIBUTED',1,'2026-01-05 10:00:00.000',203,'2026-10-25 19:32:01.049',203,0),(910000000000003041,9100000000000001001,910000000000002001,910000000000003011,'A_PLUS','A01-1','制度建设与流程优化任务完成数','CONSTRAINT','NUMBER','INCREMENT','项','HIGHER_BETTER',NULL,NULL,'统计经学校审议发布并完成流程配套或评估验收的制度制修订、议事协调和内控优化任务，同一任务不重复计数。','制度正式文本、审议记录、流程发布或验收材料。',0,NULL,25.000000,203,1,'DISTRIBUTED',1,'2026-01-05 10:00:00.000',203,'2026-10-25 19:32:01.049',203,0),(910000000000003042,9100000000000001001,910000000000002001,910000000000003011,'A_PLUS','A01-2','教学诊断与改进任务完成数','CONSTRAINT','NUMBER','INCREMENT','项','HIGHER_BETTER',NULL,NULL,'统计按年度诊改方案完成问题清单、整改实施和效果复核闭环的任务，须有复核结论。','诊改方案、问题清单、整改记录和复核报告。',0,NULL,15.000000,203,1,'DISTRIBUTED',1,'2026-01-05 10:00:00.000',203,'2026-10-25 19:32:01.049',203,0),(910000000000003043,9100000000000001001,910000000000002002,910000000000003013,'A_PLUS','A03-1','专业设置优化与数字化改造项目完成数','DEVELOPMENT','NUMBER','INCREMENT','个','HIGHER_BETTER',NULL,NULL,'统计完成专业新设、停招撤并、方向调整或人才培养方案数字化改造且经学校验收的项目，每个专业每年最多认定 1 项。','专业论证报告、备案或审批材料、人才培养方案和验收意见。',0,NULL,20.000000,203,1,'DISTRIBUTED',1,'2026-01-05 10:00:00.000',203,'2026-10-25 19:32:01.050',203,0),(910000000000003044,9100000000000001001,910000000000002003,910000000000003014,'A_PLUS','A04-1','专业课双师型教师占比','CONSTRAINT','PERCENT_QUANTIFIABLE','RATIO','%','HIGHER_BETTER',NULL,NULL,'分子为按学校认定办法有效的双师型专业课教师人数，分母为专业课教师总人数；汇总按分子分母分别加总计算。','教师名册、双师型认定文件、企业实践或职业技能证书。',0,NULL,0.700000,204,1,'DISTRIBUTED',1,'2026-01-05 10:00:00.000',203,'2026-10-25 19:32:01.050',203,0),(910000000000003045,9100000000000001001,910000000000002004,910000000000003015,'A_PLUS','A05-1','学生省级以上职业技能竞赛获奖数','DEVELOPMENT','NUMBER','INCREMENT','项','HIGHER_BETTER',NULL,NULL,'统计学生参加省级及以上职业技能竞赛并获奖的项目数，按正式获奖文件或证书落款年度认定，同一项目同一级别不重复计数。','主办单位获奖文件、证书及参赛名单。',0,NULL,120.000000,203,1,'DISTRIBUTED',1,'2026-01-05 10:00:00.000',203,'2026-10-25 19:32:01.050',203,0),(910000000000003046,9100000000000001001,910000000000002004,910000000000003016,'A_PLUS','A06-1','校企合作开发教材数','DEVELOPMENT','NUMBER','INCREMENT','部','HIGHER_BETTER',NULL,NULL,'统计与企业共同开发、通过学校教材建设验收并投入教学使用的纸质或数字教材，同一教材修订版不重复计数。','教材样书或数字资源、企业参与证明、验收意见和使用记录。',0,NULL,30.000000,203,1,'DISTRIBUTED',1,'2026-01-05 10:00:00.000',203,'2026-10-25 19:32:01.051',203,0),(910000000000003047,9100000000000001001,910000000000002005,910000000000003018,'A_PLUS','A08-1','企业横向技术服务到款额','DEVELOPMENT','NUMBER','INCREMENT','万元','HIGHER_BETTER',NULL,NULL,'以学校财务实际到账为准，统计为企业提供软件开发、数据治理、数字内容制作、技术咨询和运维等服务的横向项目到款额。','技术服务合同、项目验收或阶段成果、银行到账回单。',0,NULL,600.000000,203,1,'DISTRIBUTED',1,'2026-01-05 10:00:00.000',203,'2026-10-25 19:32:01.051',203,0),(910000000000003048,9100000000000001001,910000000000002006,910000000000003020,'A_PLUS','A10-1','校园文化品牌与实践育人项目完成数','DEVELOPMENT','NUMBER','INCREMENT','项','HIGHER_BETTER',NULL,NULL,'统计纳入年度育人方案、完成实施和总结评价的校园文化活动、志愿服务、劳动教育或社团品牌项目，常规例行活动不重复认定。','项目方案、活动记录、参与名单、总结评价和图像材料。',0,NULL,50.000000,204,1,'DISTRIBUTED',1,'2026-01-05 10:00:00.000',203,'2026-10-25 19:32:01.051',203,0),(910000000000003049,9100000000000001001,910000000000002007,910000000000003021,'A_PLUS','A11-1','办学条件与智慧校园重点项目完成数','CONSTRAINT','NUMBER','INCREMENT','项','HIGHER_BETTER',NULL,NULL,'统计纳入学校年度建设预算并完成验收的教学空间改造、实训环境改善、网络与数据治理、业务系统升级等重点项目。','项目立项与预算材料、采购合同、验收报告和投入使用记录。',0,NULL,30.000000,204,1,'DISTRIBUTED',1,'2026-01-05 10:00:00.000',203,'2026-10-25 19:32:01.051',203,0),(910000000000003050,9100000000000001001,910000000000002008,910000000000003023,'A_PLUS','A13-1','国（境）外交流与合作项目完成数','DEVELOPMENT','NUMBER','INCREMENT','项','HIGHER_BETTER',NULL,NULL,'统计完成协议签署并开展实质活动的校际交流、师生研修、课程引进或文化交流项目，仅签署意向书但未实施的不予认定。','合作协议、实施方案、活动或研修记录、项目总结。',0,NULL,12.000000,204,1,'DISTRIBUTED',1,'2026-01-05 10:00:00.000',203,'2026-10-25 19:32:01.052',203,0);
