INSERT INTO `notification` (`id`, `user_id`, `type`, `title`, `content`, `biz_type`, `biz_id`, `link`, `read_at`, `feishu_status`, `feishu_retry_count`, `feishu_next_retry_at`, `feishu_last_error`, `created_at`) VALUES (2114528995873247234,214,'REVIEW_RESULT','填报审核通过：A05-1-C04','【学生省级以上职业技能竞赛获奖数】2026 年度填报已审核通过。','submission',9100000000000070023,NULL,NULL,'SKIPPED',0,NULL,NULL,'2026-10-26 09:26:13.324'),(9100000000000110001,203,'ADJUSTMENT_TODO','新的调整申请待您初审','游戏产业学院申请将「校企合作开发教材数」（A06-1-C05）2026 年度 1 部教材任务转移至智能产业学院，请及时初审。','adjustment',9100000000000120002,'/adjustments',NULL,'SKIPPED',0,NULL,NULL,'2026-10-23 10:06:00.000'),(9100000000000110002,202,'ADJUSTMENT_TODO','调整申请待校领导审批','数字影视传媒产业学院申请将「企业横向技术服务到款额」（A08-1-C03）2026 年度 5 万元目标延期至 2027 年，校级负责人已初审通过，请审批。','adjustment',9100000000000120001,'/adjustments',NULL,'SKIPPED',0,NULL,NULL,'2026-10-21 14:21:00.000'),(9100000000000110003,211,'REVIEW_RESULT','填报已通过审核','您提交的「企业横向技术服务到款额」2026 年度填报（10 万元）已通过审核。','submission',NULL,'/workbench','2026-04-23 09:00:00.000','SKIPPED',0,NULL,NULL,'2026-04-22 09:05:00.000'),(9100000000000110004,215,'REVIEW_RESULT','填报被驳回','您提交的「企业横向技术服务到款额」2026 年度填报（5 万元）被驳回。审核意见：合同服务内容与到款用途对应关系不清，请补充项目清单和到账说明。','submission',NULL,'/workbench',NULL,'SKIPPED',0,NULL,NULL,'2026-08-08 11:25:00.000'),(9100000000000110005,217,'TASK_DISTRIBUTED','新任务待接收','您有新的 B+ 任务待接收：A03-1-C07 专业设置优化与数字化改造项目完成数（2026—2030 年）。','task',NULL,'/workbench',NULL,'SKIPPED',0,NULL,NULL,'2026-01-15 10:01:00.000'),(9100000000000110006,218,'REVIEW_RESULT','填报被驳回','您提交的「学生省级以上职业技能竞赛获奖数」2026 年度填报（1 项）被驳回。审核意见：请补充主办单位盖章的参赛学生名单。','submission',NULL,'/workbench',NULL,'SKIPPED',0,NULL,NULL,'2026-09-18 10:05:00.000'),(9100000000000110007,213,'REVIEW_RESULT','填报已通过审核','您提交的「企业横向技术服务到款额」2026 年度填报（2 万元）已通过审核。','submission',NULL,'/workbench','2026-06-16 08:30:00.000','SKIPPED',0,NULL,NULL,'2026-06-15 09:05:00.000'),(9100000000000110008,216,'DEADLINE_REMINDER','2026 年度填报截止提醒','2026 年度填报将于 12 月 31 日截止，您负责的校企合作教材和实训条件建设项目尚需完成审核或补正，请合理安排进度。',NULL,NULL,'/workbench',NULL,'SKIPPED',0,NULL,NULL,'2026-10-20 09:00:00.000'),(9100000000000110009,204,'WARNING','年度目标推进提醒','「校内实训工位规模」2026 年当前审核通过值为 3350 个，年度目标为 3400 个，请跟进改造项目验收与资产登记。',NULL,NULL,'/plans',NULL,'SKIPPED',0,NULL,NULL,'2026-10-22 09:00:00.000');
